import React, { useMemo, useState } from 'react';
import {
  SearchInput,
  apiClient,
  createIncidentLocationSearchConfig,
  unwrap,
  type BffResponse,
  type IncidentLocationMode,
} from '@linm-soft-org/linm-web-common-components';
import styles from './IncidentLocationSearchInput.module.css';

interface IncidentLocationSearchInputProps {
  mode: IncidentLocationMode;
  value: string;
  onChange: (value: string) => void;
  label?: string;
  required?: boolean;
  disabled?: boolean;
  error?: string;
  placeholder?: string;
  showLabel?: boolean;
}

type LocationType = 'room' | 'specific_location';

const TYPE_OPTIONS: { value: LocationType; label: string; icon: string }[] = [
  { value: 'room', label: 'Phòng', icon: 'fas fa-door-open' },
  { value: 'specific_location', label: 'Vị trí', icon: 'fas fa-map-marker-alt' },
];

function useLocationSearchConfig(mode: IncidentLocationMode) {
  return useMemo(() => {
    const base = createIncidentLocationSearchConfig({ mode });
    return {
      ...base,
      dropdownPortal: true,
      dropdownMatch: 'container' as const,
      dropdownMinWidth: '28rem',
      dropdownMaxWidth: 'min(720px, calc(100vw - 32px))',
      columns: (base.columns ?? []).map((col) => {
        if (col.key === 'type') return { ...col, width: '6.5rem', align: 'start' as const };
        if (col.key === 'name') return { ...col, width: 'minmax(12rem, 1fr)', align: 'start' as const };
        return col;
      }),
    };
  }, [mode]);
}

async function createLocation(name: string, type: LocationType): Promise<{ name: string }> {
  const res = await apiClient.post<BffResponse<{ name: string }>>('/incident-locations', { name, type });
  return unwrap(res);
}

export const IncidentLocationSearchInput: React.FC<IncidentLocationSearchInputProps> = ({
  mode,
  value,
  onChange,
  label,
  required = false,
  disabled = false,
  error,
  placeholder,
  showLabel = true,
}) => {
  const config = useLocationSearchConfig(mode);
  const [showModal, setShowModal] = useState(false);
  const [modalName, setModalName] = useState('');
  const [modalType, setModalType] = useState<LocationType>('room');
  const [saving, setSaving] = useState(false);

  const defaultPlaceholder = mode === 'department_room'
    ? 'Tìm khoa, phòng hoặc vị trí...'
    : 'Tìm vị trí cụ thể...';

  const confirmCreate = async () => {
    const name = modalName.trim();
    if (!name || saving) return;
    setSaving(true);
    try {
      const created = await createLocation(name, modalType);
      onChange(created.name);
      setShowModal(false);
    } catch {
      /* keep the dialog open so the user can retry */
    } finally {
      setSaving(false);
    }
  };

  return (
    <>
      <SearchInput
        config={config}
        value={value || undefined}
        primaryDisplay={value || undefined}
        onChange={(item) => onChange(item.name)}
        onClear={() => onChange('')}
        label={label}
        showLabel={showLabel}
        placeholder={placeholder ?? defaultPlaceholder}
        required={required}
        disabled={disabled}
        error={error}
        showSecondaryInput={false}
        renderDropdownFooter={({ term, close }) => (
          <button
            type="button"
            className={styles.addNewBtn}
            onClick={() => {
              setModalName(term.trim());
              setModalType(mode === 'specific_location' ? 'specific_location' : 'room');
              setShowModal(true);
              close();
            }}
          >
            <i className="fas fa-plus" />
            {term.trim() ? ` Thêm bản ghi "${term.trim()}"` : ' Thêm bản ghi mới'}
          </button>
        )}
      />
      {showModal && (
        <div className={styles.modalOverlay} onClick={() => !saving && setShowModal(false)}>
          <div className={styles.modal} onClick={(e) => e.stopPropagation()} role="dialog" aria-modal="true">
            <div className={styles.modalHeader}>
              <span className={styles.modalTitle}>
                <i className="fas fa-plus-circle" /> Thêm phòng/ vị trí mới
              </span>
              <button type="button" className={styles.modalClose} onClick={() => setShowModal(false)} disabled={saving}>
                ✕
              </button>
            </div>
            <form
              onSubmit={(e) => {
                e.preventDefault();
                void confirmCreate();
              }}
            >
              <div className={styles.modalBody}>
                <label className={styles.modalLabel}>
                  Tên phòng/ vị trí <span className={styles.required}>*</span>
                </label>
                <input
                  className={styles.modalInput}
                  value={modalName}
                  onChange={(e) => setModalName(e.target.value)}
                  placeholder="Nhập tên phòng/ vị trí..."
                  autoFocus
                  required
                />
                <label className={styles.modalLabel}>
                  Loại <span className={styles.required}>*</span>
                </label>
                <div className={styles.typeGrid}>
                  {TYPE_OPTIONS.map((opt) => (
                    <button
                      key={opt.value}
                      type="button"
                      className={`${styles.typeCard} ${modalType === opt.value ? styles.typeCardActive : ''}`}
                      onClick={() => setModalType(opt.value)}
                    >
                      <i className={opt.icon} />
                      <span>{opt.label}</span>
                    </button>
                  ))}
                </div>
              </div>
              <div className={styles.modalFooter}>
                <button type="button" className={styles.btnCancel} onClick={() => setShowModal(false)} disabled={saving}>
                  Hủy
                </button>
                <button type="submit" className={styles.btnConfirm} disabled={saving || !modalName.trim()}>
                  {saving ? 'Đang lưu...' : 'Thêm'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </>
  );
};
